let academySection=null,libraryData=null,libraryLoading=false,libraryPromise=null,libraryError='',libraryFilter={q:'',subject:'all',format:'all',provider:'nunya',topic:'all',level:'all',page:1},manifest=null,eduData=null,curriculumData=null,sectorEvidence=null,resourceCurrent=null,resourceTrail=[],runtimeWorker=null,runtimeTimer=null,runId=0,assessmentBank=null;
state.resourceDone=state.resourceDone||[];state.resourceSaved=state.resourceSaved||[];state.resourceNotes=state.resourceNotes||{};state.errors=state.errors||{};state.mastery=state.mastery||{};state.reviewSchedule=state.reviewSchedule||{};state.events=state.events||[];state.preferredTrack=state.preferredTrack||'both';state.fontScale=state.fontScale||1;state.lowData=state.lowData??true;
const readJson=async url=>{const r=await fetch(url);if(!r.ok)throw Error('Ressource indisponible ('+r.status+').');return r.json()};
async function references(){if(!eduData){[eduData,curriculumData,sectorEvidence]=await Promise.all([readJson('./data/togo_education_system.json'),readJson('./data/togo_curriculum.json'),readJson('./data/togo_sectors.json')])}}
async function loadManifest(){try{manifest=await readJson('./library/manifest.json');if(!$('#modal').hidden)return;render()}catch{}}
async function loadLibrary(){if(libraryData)return libraryData;if(libraryPromise)return libraryPromise;libraryLoading=true;libraryError='';libraryPromise=(async()=>{try{const rows=await readJson('./library/index.json');if(!Array.isArray(rows)||!rows.every(r=>typeof r.id==='string'&&typeof r.title==='string'))throw Error('Catalogue invalide.');libraryData=rows;return rows}catch{libraryError='Le catalogue n’a pas pu être chargé. Connecte-toi une première fois, puis réessaie.'}finally{libraryLoading=false;libraryPromise=null;if(page==='explore'||page==='downloads')render()}})();return libraryPromise}

function statsTrack(track){const list=courses.filter(c=>c.track===track),done=list.reduce((n,c)=>n+doneCount(c),0);return {done,total:list.reduce((n,c)=>n+c.lessons.length,0)}}
function eventLocal(type,detail={}){state.events.push({type,date:new Date().toISOString(),...detail});state.events=state.events.slice(-1000);persist()}
function setSection(section){academySection=section;selectedDetail=null;selectedSector=null;page=section==='library'?'explore':'home';history.pushState({},'','#/'+({school:'mes-cours',review:'revision',profile:'profil',privacy:'confidentialite',library:'cours'})[section]);render();window.scrollTo({top:0,behavior:'instant'});if(section==='school')references().then(()=>{if(academySection==='school')render()}).catch(()=>toast('Les repères scolaires ne sont pas disponibles pour le moment.'))}
