function routeAcademy(){const route=location.hash.replace(/^#\/?/,'').split('/');const map={'mes-cours':'school',revision:'review',profil:'profile',confidentialite:'privacy'};academySection=map[route[0]]||null;if(['cours','metiers'].includes(route[0])){selectedDetail=route[0]==='cours'&&courses.some(c=>c.id===route[1])?route[1]:null;selectedSector=route[0]==='metiers'&&SECTORS.some(s=>s.id===route[1])?route[1]:null;page=route[0]==='cours'?'explore':'careers';render()}if(academySection){page='home';selectedDetail=null;selectedSector=null;render();if(academySection==='school')references().then(()=>{if(academySection==='school')render()}).catch(()=>{})}if(route[0]==='ressource'){academySection=null;page='explore';selectedDetail=null;openResource(route[1],false)}}

render=function(){legacy.render();document.documentElement.lang='fr-TG';if(academySection){const view={school:schoolView,review:reviewView,profile:settingsView,privacy:privacyView};$('#main').innerHTML=view[academySection]();$('#breadcrumb-current').textContent=({school:'Mes cours',review:'Révision',profile:'Mon profil',privacy:'Confidentialité'})[academySection];hydrate()}document.body.classList.toggle('dark',state.theme==='dark');document.body.classList.toggle('reading-font',!!state.readingFont);document.documentElement.style.setProperty('--font-scale',state.fontScale);$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.section===academySection||(!academySection&&b.dataset.page===page)));if($('.nav-pill'))$('.nav-pill').textContent=manifest?'11k':'…';if($('[data-i="explore"]'))$('[data-i="explore"]').textContent='Bibliothèque';if(page==='explore'&&!selectedDetail)$('#breadcrumb-current').textContent='Bibliothèque';$('#sidebar').inert=!$('#modal').hidden||(matchMedia('(max-width:700px)').matches&&!$('#sidebar').classList.contains('open'));};
homeView=function(){const school=statsTrack('school'),future=statsTrack('future');const trackCards=`<section class="track-choice"><button data-section="school" class="track-school"><span>✎</span><small>RÉUSSIR AU QUOTIDIEN</small><h2>Mes cours</h2><p>Réviser une matière, comprendre une méthode, préparer mes examens.</p><strong>CEPD · BEPC · BAC I · BAC II</strong><b>Réviser mes cours →</b></button><button class="track-future" data-page="careers"><span>✳</span><small>OUVRIR DES POSSIBLES</small><h2>Mon avenir</h2><p>Explorer un métier et construire des compétences qui me ressemblent.</p><strong>${SECTORS.length} domaines · ${SECTORS.reduce((n,s)=>n+s.jobs.length,0)} chemins</strong><b>Explorer mon avenir →</b></button></section>`;const discovery=`<section class="library-invite"><div><span class="eyebrow">UNE BIBLIOTHÈQUE QUI S’OUVRE À TOI</span><h2>${manifest?manifest.resources.toLocaleString('fr-FR'):'Des milliers de'} ressources en français.</h2><p>Des articles à lire ici, des vidéos à ton choix et des parcours pour avancer.</p></div><button class="primary" data-page="explore">Ouvrir la bibliothèque →</button></section>`;let html=legacy.home();html=html.replace('<section class="hero">',trackCards+'<section class="hero">');html=html.replace('<section class="recommended">',discovery+'<section class="recommended">');html=html.replace('Découvre l’informatique, développe tes talents et construis ton chemin.','Découvre des savoirs, développe tes talents et construis ton chemin.');if(state.preferredTrack==='school')html=html.replace('class="track-choice"','class="track-choice school-first"');html+=`<div class="track-progress-summary"><span>Mes cours : ${school.done} leçons</span><span>Mon avenir : ${future.done} leçons</span><button class="text-button" data-section="review">Ma révision du jour →</button></div>`;return html};
exploreView=function(){if(selectedDetail)return legacy.explore();return libraryView()};
function libraryView(){if(libraryFilter.provider!=='nunya'&&!libraryData&&!libraryLoading)queueMicrotask(loadLibrary);const items=filteredResources(),pageCount=Math.max(1,Math.ceil(items.length/24));libraryFilter.page=Math.min(libraryFilter.page,pageCount);const visible=items.slice((libraryFilter.page-1)*24,libraryFilter.page*24);return `<section class="catalog-hero library-hero"><div><span class="eyebrow">LIRE. ESSAYER. COMPRENDRE. ALLER PLUS LOIN.</span><h1>Bibliothèque</h1><p>Des cours et des ressources pour comprendre, puis pratiquer.</p><div class="catalog-facts"><span>${manifest?manifest.resources.toLocaleString('fr-FR'):'…'} ressources</span><i></i><span>${courses.length} parcours guidés</span><i></i><span>${SECTORS.length} domaines métiers</span></div></div><div class="catalog-art" aria-hidden="true"><div class="floating-card fc-one">&lt;/&gt;<small>CRÉER</small></div><div class="floating-card fc-two">½<small>COMPRENDRE</small></div><div class="floating-card fc-three">❧<small>EXPLORER</small></div><span class="catalog-spark">✳</span></div></section><div class="library-tabs"><button class="${libraryFilter.provider==='nunya'?'active':''}" data-library-tab="nunya">Parcours guidés <span>${courses.length}</span></button><button class="${libraryFilter.provider==='nunya'?'':'active'}" data-library-tab="resources">Ressources <span>${manifest?manifest.resources.toLocaleString('fr-FR'):'…'}</span></button><button data-page="careers">Par métier ↗</button><button data-section="school">Par classe ↗</button></div><section class="library-controls"><label class="library-search">${icon('search')}<input id="library-search" type="search" value="${esc(libraryFilter.q)}" placeholder="Python, fonctions, cellules, énergie, CSS…" aria-label="Rechercher dans la bibliothèque"></label><div class="library-selects" ${libraryFilter.provider==='nunya'?'hidden':''}><label>Format<select id="library-format"><option value="all">Tous les formats</option><option value="article" ${libraryFilter.format==='article'?'selected':''}>Articles à lire</option><option value="video" ${libraryFilter.format==='video'?'selected':''}>Vidéos en français</option></select></label><label>Niveau<select id="library-level"><option value="all">Tous les niveaux</option><option value="beginner" ${libraryFilter.level==='beginner'?'selected':''}>Pour débuter</option><option value="reference" ${libraryFilter.level==='reference'?'selected':''}>Approfondir / référence</option></select></label></div></section><div class="subject-tabs">${librarySubjects().map(([id,label,glyph])=>`<button class="subject-tab ${libraryFilter.subject===id?'selected':''}" data-library-subject="${id}" aria-pressed="${libraryFilter.subject===id}"><span>${glyph}</span>${label}</button>`).join('')}</div>${libraryFilter.subject==='technology'&&libraryFilter.provider!=='nunya'?`<div class="topic-chips">${[['all','Tout le numérique'],['web','Apprendre le web'],['html','HTML'],['css','CSS'],['javascript','JavaScript'],['network','HTTP & sécurité'],['api','API du navigateur'],['systems','WebAssembly'],['glossary','Vocabulaire']].map(([id,label])=>`<button class="${libraryFilter.topic===id?'selected':''}" data-library-topic="${id}">${label}</button>`).join('')}</div>`:''}<div class="catalog-results-line"><span id="resource-count">${libraryFilter.provider==='nunya'?filteredOriginal().length+' parcours guidés':items.length.toLocaleString('fr-FR')+' ressources disponibles'}</span><span>${libraryFilter.provider==='nunya'?'Article · exemple · exercice · progression':'Articles MDN · vidéos Khan Academy'}</span></div><div id="library-results">${libraryFilter.provider==='nunya'?guidedCoursesView():libraryError?`<div class="empty-state"><p>${libraryError}</p><button class="secondary" data-ac="retry-library">Réessayer</button></div>`:!libraryData?'<div class="loading-library" role="status">Ouverture de la bibliothèque… Les ressources sont chargées à la demande pour économiser tes données.</div>':`<div class="resource-grid">${visible.length?visible.map(resourceCard).join(''):'<div class="empty-state"><h3>On n’a pas encore trouvé ce sujet.</h3><p>Essaie un autre mot ou enlève un filtre.</p><button class="secondary" data-ac="clear-library">Tout afficher</button></div>'}</div><div class="pagination"><button class="secondary" data-library-page="prev" ${libraryFilter.page<=1?'disabled':''}>← Précédent</button><span>Page ${libraryFilter.page} / ${pageCount}</span><button class="secondary" data-library-page="next" ${libraryFilter.page>=pageCount?'disabled':''}>Suivant →</button></div>`}</div><div class="resource-disclosure"><strong>Des ressources identifiées, des progrès qui t’appartiennent.</strong><p>Les articles MDN sont réutilisés sous licence CC BY-SA 2.5 et lisibles dans Nunya. Les vidéos Khan Academy sont intégrées depuis leur lecteur officiel et nécessitent une connexion. Les parcours Nunya sont des brouillons pédagogiques à relire. La correspondance avec le programme togolais est à confirmer.</p></div>`}
function filteredOriginal(){return courses.filter(c=>(libraryFilter.subject==='all'||c.domain===(libraryFilter.subject==='technology'?'tech':libraryFilter.subject))&&normalize(c.title+' '+c.desc).includes(normalize(libraryFilter.q)))}
function filteredResources(){if(!libraryData)return [];const q=normalize(libraryFilter.q);return libraryData.filter(r=>(libraryFilter.subject==='all'||r.s===(libraryFilter.subject==='technology'?'tech':libraryFilter.subject))&&(libraryFilter.format==='all'||r.f===libraryFilter.format)&&(libraryFilter.level==='all'||r.l===libraryFilter.level)&&(libraryFilter.topic==='all'||r.t===libraryFilter.topic)&&(!q||normalize(r.title+' '+r.c+' '+r.u+' '+r.t).includes(q)))}
function resourceCard(r){return `<article class="resource-card"><button data-resource="${r.id}" class="resource-card-top ${r.f==='article'?'article-top':'video-top'}"><span>${r.f==='article'?'Aa':'▷'}</span><small>${r.p==='mdn'?'MDN WEB DOCS':'KHAN ACADEMY FR'}</small><i>${r.f==='article'?'ARTICLE EN FRANÇAIS':'AUDIO FRANÇAIS'}</i></button><div><small class="resource-collection">${esc(r.c)}</small><h3><button data-resource="${r.id}">${esc(r.title)}</button></h3><p>${r.f==='article'?'À lire ici · enregistrable hors ligne':'À regarder ici · connexion nécessaire'}${r.d?' · '+Math.max(1,Math.ceil(r.d/60))+' min':''}</p><div class="resource-card-actions"><button data-resource="${r.id}">${state.resourceDone.includes(r.id)?'✓ Revoir':'Découvrir'} →</button>${r.f==='article'?`<button data-save-resource="${r.id}" aria-label="Enregistrer ${esc(r.title)}">${icon(state.resourceSaved.includes(r.id)?'check':'download')}</button>`:''}</div></div></article>`}
function safeArticle(html){const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('script,style,iframe,object,embed,form,link,meta,img,svg,math').forEach(n=>n.remove());for(const el of doc.body.querySelectorAll('*'))for(const a of [...el.attributes])if(!['href','colspan','rowspan'].includes(a.name)||a.name==='href'&&!/^(https?:|\/|#)/i.test(a.value))el.removeAttribute(a.name);return doc.body.innerHTML}
async function articleData(r){return readJson('./library/articles/'+r.id+'.json')}
async function openResource(id,push=true){await loadLibrary();const r=libraryData?.find(x=>x.id===id);if(!r){toast('Cette ressource n’est pas disponible.');return}if(resourceCurrent&&resourceCurrent.id!==id)resourceTrail.push(resourceCurrent.id);resourceCurrent=r;if(push)history.pushState({},'','#/ressource/'+id);modal(`<span class="eyebrow">${r.p==='mdn'?'MDN WEB DOCS · ARTICLE':'KHAN ACADEMY FRANCOPHONE · VIDÉO'}</span><h2 id="modal-title">${esc(r.title)}</h2><div class="loading-library" role="status">Ouverture de la ressource…</div>`,true);try{const data=r.f==='article'?await articleData(r):null;if(resourceCurrent?.id!==id||$('#modal').hidden)return;modal(`<div class="resource-reader-top"><button class="text-button" data-ac="back-resource">← ${resourceTrail.length?'Ressource précédente':'La bibliothèque'}</button><span class="tag">${r.p==='mdn'?'MDN · CC BY-SA 2.5':'KHAN ACADEMY · CC BY-NC-SA'}</span></div><h2 id="modal-title">${esc(r.title)}</h2><p class="resource-reader-meta">${esc(r.c)}${r.u?' · '+esc(r.u):''}</p>${r.f==='video'?`<div class="video-screen" id="resource-video"><button class="video-load" data-library-video="${r.v}"><span class="play-circle">▶</span><strong>${esc(r.title)}</strong><small>Lire la vidéo ici · audio français</small></button></div>${writtenAlternative(r)}<p>Cette vidéo est un complément. Tu peux garder une note, relire tes cours et travailler les exercices sans vidéo.</p>`:`<div class="article-adaptation-note">Article de MDN, adapté à la lecture dans Nunya. Les démonstrations interactives de la source ne sont pas reproduites. Pour pratiquer le code, ouvre notre atelier. <button class="text-button" data-ac="workshop">Ouvrir l’atelier →</button></div><div class="article-reader">${safeArticle(data.html)}</div>`}<div class="resource-completion"><button class="primary" data-complete-resource="${id}">${state.resourceDone.includes(id)?'✓ Ressource terminée':'Marquer comme étudiée'} ${icon('check')}</button>${r.f==='article'?`<button class="secondary" data-save-resource="${id}">${icon('download')}${state.resourceSaved.includes(id)?'Enregistrée':'Enregistrer hors ligne'}</button>`:''}${r.p==='mdn'?'<button class="secondary" data-ac="workshop">Essayer le code dans cet article</button>':''}</div><section class="reflection"><label for="resource-note">Ce que je retiens / ma question</label><textarea id="resource-note" maxlength="2000" rows="3">${esc(state.resourceNotes[id]||'')}</textarea><button class="text-button" data-ac="save-resource-note">Garder ma note ✓</button></section><details class="lesson-sources"><summary>Source, licence et limites</summary><p>${r.p==='mdn'?'MDN Web Docs et ses contributeurs. Texte sous CC BY-SA 2.5, exemples de code sous les conditions détaillées dans la licence MDN. Mise en forme adaptée ; macros interactives et images omises.':'Khan Academy et ses contributeurs. Métadonnées issues de l’export public, sélection des vidéos déclarées doublées en français. Lecture dans le lecteur officiel ; aucune vidéo n’est copiée.'}</p><p>Cette ressource n’est pas présentée comme conforme au programme togolais. Aucun contenu n’a été relu ici par un enseignant togolais.</p><a href="${esc(r.url)}" target="_blank" rel="noopener">Source originale ↗</a> · <a href="${r.p==='mdn'?'https://creativecommons.org/licenses/by-sa/2.5/':'https://creativecommons.org/licenses/by-nc-sa/3.0/'}" target="_blank" rel="noopener">Licence ↗</a></details>`,true);rewriteArticleLinks();eventLocal('resource_open',{resourceId:id})}catch{modal(`<h2 id="modal-title">Cette ressource n’est pas encore enregistrée.</h2><p>Connecte-toi pour l’ouvrir une première fois. Les articles enregistrés restent accessibles depuis Mes téléchargements.</p><button class="secondary" data-ac="back-resource">Revenir à la bibliothèque</button>`)}}
function rewriteArticleLinks(){$$('.article-reader a').forEach(a=>{const href=a.getAttribute('href');if(href?.startsWith('/fr/docs/')){const url='https://developer.mozilla.org'+href.split('#')[0];const match=libraryData.find(r=>r.url.toLowerCase()===url.toLowerCase());if(match){a.href='#/ressource/'+match.id;a.dataset.articleResource=match.id}else{a.href='https://developer.mozilla.org'+href;a.target='_blank';a.rel='noopener'}}else if(href&&!href.startsWith('#')){a.target='_blank';a.rel='noopener'}})}
async function saveResource(id){await loadLibrary();const r=libraryData?.find(x=>x.id===id);if(!r||r.f!=='article')return;try{await articleData(r);const cache=await caches.open('nunya-library-v1');const url=new URL('./library/articles/'+id+'.json',location.href);await cache.addAll([url,new URL('./library/index.json',location.href),new URL('./library/manifest.json',location.href)]);if(!state.resourceSaved.includes(id))state.resourceSaved.push(id);persist();toast('Article enregistré : retrouve-le dans Mes téléchargements.');if(page==='downloads')render()}catch{toast('Impossible d’enregistrer cet article. Vérifie ta connexion et ton espace disponible.')}}
const previousDownloads=downloadsView;downloadsView=function(){let html=previousDownloads();const saved=state.resourceSaved.map(id=>libraryData?.find(r=>r.id===id)).filter(Boolean);html+=`<section class="panel saved-library"><h3>Mes ressources enregistrées <span>${state.resourceSaved.length}</span></h3>${saved.length?saved.map(r=>`<div class="saved-row"><button data-resource="${r.id}">${esc(r.title)}</button><button class="text-button" data-remove-resource="${r.id}">Retirer</button></div>`).join(''):state.resourceSaved.length?'<p>Ouvre la bibliothèque pour retrouver les titres de tes articles enregistrés.</p>':'<p>Dans la bibliothèque, utilise le bouton de téléchargement d’un article.</p>'}<div class="modal-actions"><button class="secondary" data-ac="export-module">Partager un parcours hors ligne</button><button class="secondary" data-ac="import-module">Importer un parcours</button><button class="secondary" data-ac="storage">Voir l’espace utilisé</button></div><p class="profile-line" id="storage-result"></p></section>`;if(!libraryData&&state.resourceSaved.length)queueMicrotask(loadLibrary);return html};
function schoolView(){const selected=state.profile.school||'Seconde';return `<section class="school-hero"><span class="eyebrow">MES COURS · UNE MÉTHODE, UN PEU CHAQUE JOUR</span><h1>Comprendre aujourd’hui.<br><em>Réussir à ton rythme.</em></h1><p>Des résumés, des exemples et des exercices pour consolider tes bases. Les liens avec le programme togolais sont en cours de relecture.</p><div class="school-class"><label>Ma classe<select id="school-class">${(eduData?.classes||[{cycle:'Collège',classes:['6ème','5ème','4ème','3ème']},{cycle:'Lycée',classes:['Seconde','Première','Terminale']}]).map(group=>`<optgroup label="${group.cycle}">${group.classes.map(c=>`<option ${selected===c?'selected':''}>${c}</option>`).join('')}</optgroup>`).join('')}<option ${selected==='Université'?'selected':''}>Université</option><option ${selected==='Autodidacte'?'selected':''}>Autodidacte</option></select></label><label>Ma série<select id="school-series"><option value="">Non précisée</option>${(curriculumData?.series||[]).map(s=>`<option value="${s.id}" ${state.profile.series===s.id?'selected':''}>${s.label}</option>`).join('')}</select></label></div></section><section class="exam-band"><div><span>✧</span><h2>Un repère pour chaque étape.</h2><p>CEPD · BEPC · BAC I · BAC II</p></div><div><strong>${({'CM2':'CEPD','3ème':'BEPC','Première':'BAC I','Terminale':'BAC II'})[selected]||'Objectif de classe'}</strong><small>${selected==='Seconde'?'Pas d’examen national présumé en seconde.':'Calendrier et modalités à confirmer auprès de ton établissement.'}</small><button class="text-button" data-ac="exam-plan">Préparer mon calendrier de révision →</button></div></section><div class="section-heading"><h2>Quelle matière aujourd’hui ?</h2><button class="text-button" data-section="review">Mes révisions →</button></div><div class="school-subject-grid">${(curriculumData?.subjects||[]).map(s=>`<button data-school-subject="${s.id}"><span>${({maths:'½',physics:'ϟ',biology:'◎',french:'Aa',english:'Hello',history:'◷',civics:'◇',philosophy:'?'})[s.id]}</span><strong>${s.label}</strong><small>Résumé · méthode · exercice →</small></button>`).join('')||'<div class="loading-library">Chargement des matières…</div>'}</div><div class="info-banner">${icon('book')}<div><strong>Des exercices originaux, un programme à vérifier.</strong><p>Le dossier officiel partagé répertorie les sujets du BEPC. Nunya distingue ce référencement des correspondances de programme, des coefficients et des dates, qui nécessitent leur propre vérification. Les contenus de primaire et de début de collège seront développés ; aucun parcours complet n’est annoncé pour ces classes.</p></div></div>`}
function schoolSubject(id){const s=curriculumData?.subjects.find(x=>x.id===id);if(!s)return;modal(`<span class="eyebrow">MES COURS · ${esc(state.profile.school||'Seconde')}</span><h2 id="modal-title">${s.label}</h2><p>Un point de départ pour réviser. La correspondance avec ta classe et ta série est à relire par un enseignant.</p><div class="modal-actions"><button class="primary" data-school-course="${state.profile.school==='Terminale'?({maths:'terminale-analyse',physics:'terminale-mecanique'})[id]||s.course:s.course}">Résumé, méthode et exercices →</button><button class="secondary" data-subject-library="${s.library}">Ressources complémentaires</button>${id==='maths'?'<button class="secondary" data-ac="mock-exam">Entraînement original corrigé</button>':''}</div><details class="lesson-sources"><summary>Sources officielles et examens</summary><p>Le dossier BEPC fourni comporte notamment les matières Mathématiques, PCT, SVT, Français, Anglais, Histoire-Géographie et ECM. Source consultée le 1er novembre 2026.</p><a href="https://ecole.gouv.tg/college/mod/folder/view.php?id=22&lang=fr" target="_blank" rel="noopener">Dossier officiel BEPC ↗</a><p>Les sujets d’annales ne sont pas copiés dans Nunya. Une procédure d’import avec droits et validation est prévue pour l’équipe pédagogique.</p></details>`)}
function reviewView(){const due=Object.entries(state.reviewSchedule).filter(([,v])=>v<=dayKey()),errors=Object.entries(state.errors);return `<h1 class="page-title">Un petit rappel. Un nouveau déclic.</h1><p class="page-subtitle">Reviens sur une idée en cinq minutes. Les erreurs sont des indices pour apprendre.</p><div class="review-summary"><span><strong>${due.length}</strong> notions à revoir</span><span><strong>${errors.length}</strong> exercices dans mon carnet</span><span><strong>${Object.values(state.mastery).filter(m=>m.level==='mastered').length}</strong> notions consolidées</span></div><section class="panel"><h3>Ma révision du jour</h3>${due.length?due.slice(0,8).map(([key])=>reviewRow(key)).join(''):'<p>Pas de rappel prévu aujourd’hui. Après une leçon, Nunya proposera un retour espacé sur la notion.</p>'}</section><section class="panel notebook"><h3>Mon carnet d’erreurs</h3>${errors.length?errors.slice(-12).reverse().map(([key,value])=>reviewRow(key,'Dernier essai : '+value.date)).join(''):'<p>Un exercice qui te fait hésiter apparaîtra ici. Il n’y a aucun point à perdre.</p>'}</section><div class="modal-actions"><button class="primary" data-page="explore">Choisir une nouvelle découverte →</button><button class="secondary" data-ac="glossary">Mon glossaire FR / EN</button></div>`}
function reviewRow(key,extra=''){const [id,num]=key.split(':'),c=getCourse(id),l=c.lessons[Number(num)];if(!l)return '';return `<div class="review-row"><div><strong>${esc(l.title)}</strong><small>${esc(c.title)}${extra?' · '+extra:''}</small></div><button class="secondary" data-review-lesson="${key}">Revoir →</button></div>`}
verify=function(){if(quizSelection!==null&&activeCourse){const key=activeCourse.id+':'+activeLesson,right=quizSelection===activeCourse.lessons[activeLesson].answer,prev=state.mastery[key]||{attempts:0,successes:0};prev.attempts++;if(right){prev.successes++;prev.level=prev.successes>=2?'mastered':'familiar';delete state.errors[key];const d=new Date();d.setDate(d.getDate()+(prev.successes>=3?7:prev.successes===2?3:1));state.reviewSchedule[key]=dayKey(d)}else{prev.level='tried';state.errors[key]={date:dayKey(),course:activeCourse.id};state.reviewSchedule[key]=dayKey()}state.mastery[key]=prev;eventLocal('lesson_answer',{course:activeCourse.id,lesson:activeLesson,right});persist()}legacy.verify()};
function examPlan(){const selected=state.profile.school||'Seconde',goal=state.examGoal||{};modal(`<span class="eyebrow">MON PLAN PERSONNEL · SANS PRESSION</span><h2 id="modal-title">Un peu de place pour réviser.</h2><p>Choisis la date donnée par ton établissement ou une date personnelle. Nunya n’affiche pas de calendrier officiel non vérifié.</p><form id="exam-plan-form"><label class="field">Date de mon objectif<input type="date" name="date" min="${dayKey()}" value="${esc(goal.date||'')}" required></label><label class="field">Minutes par jour<select name="minutes">${[10,15,20,30].map(n=>`<option ${goal.minutes===n?'selected':''}>${n}</option>`).join('')}</select></label><button class="primary">Créer mon plan →</button></form>${goal.date?`<div class="assessment-result"><strong>${Math.max(0,Math.ceil((new Date(goal.date+'T12:00:00')-new Date())/86400000))} jours pour mon objectif personnel</strong><p>Commence par les notions de ton carnet d’erreurs, puis alterne une notion revue et une notion nouvelle. ${Object.keys(state.errors).length} notion(s) sont actuellement à reprendre.</p><button class="secondary" data-section="review">Voir mes priorités</button></div>`:''}`)}
function mockExam(){modal(`<span class="eyebrow">ENTRAÎNEMENT ORIGINAL NUNYA · À RELIRE</span><h2 id="modal-title">Préparer une sortie scolaire.</h2><p>Exemple pédagogique, sans reproduction d’une annale ni revendication de format officiel. Une sortie a un coût fixe de 2 000 FCFA et coûte 500 FCFA par personne.</p><form id="mock-form"><label class="field">1. Budget pour 10 personnes (FCFA)<input name="a" inputmode="decimal" required></label><label class="field">2. Budget pour 12 personnes (FCFA)<input name="b" inputmode="decimal" required></label><label class="field">3. Coût supplémentaire pour passer de 10 à 12 personnes (FCFA)<input name="c" inputmode="decimal" required></label><label class="field">4. Avec 12 000 FCFA, nombre maximal de personnes<input name="d" inputmode="numeric" required></label><button class="primary">Comparer avec le corrigé →</button></form><div id="mock-correction" aria-live="polite"></div>`)}
function settingsView(){return `<h1 class="page-title">Un espace à ta façon.</h1><p class="page-subtitle">Ton niveau compte davantage que ton âge. Tu peux changer de classe et de parcours.</p><div class="settings-grid"><section class="panel"><h3>Mon objectif</h3><div class="goal-options">${[['school','Mes cours et mes examens'],['future','Découvrir les métiers et compétences'],['both','Les deux']].map(([v,label])=>`<button class="assessment-option ${state.preferredTrack===v?'selected':''}" data-goal="${v}" aria-pressed="${state.preferredTrack===v}">${label}</button>`).join('')}</div><button class="secondary" data-ac="edit-profile">Modifier ma classe et mon expérience</button></section><section class="panel"><h3>Confort de lecture</h3><div class="setting-line"><span>Thème sombre</span><button class="toggle ${state.theme==='dark'?'on':''}" data-setting="theme" role="switch" aria-checked="${state.theme==='dark'}" aria-label="Thème sombre"></button></div><div class="setting-line"><span>Police de lecture espacée</span><button class="toggle ${state.readingFont?'on':''}" data-setting="readingFont" role="switch" aria-checked="${!!state.readingFont}" aria-label="Police de lecture espacée"></button></div><div class="setting-line"><span>Taille du texte</span><button class="secondary" data-font="smaller" aria-label="Réduire le texte">A−</button><button class="secondary" data-font="larger" aria-label="Agrandir le texte">A+</button></div></section><section class="panel"><h3>Appareil partagé</h3><p>Chaque profil local possède ses propres progrès. Aucun compte en ligne n’est créé.</p><button class="secondary" data-ac="profiles">Choisir ou créer un profil local</button></section><section class="panel"><h3>Mes données</h3><p>Profil, notes, progrès et retours restent dans ce navigateur. Tu peux les sauvegarder et les supprimer.</p><div class="modal-actions"><button class="secondary" data-action="export">Sauvegarder</button><button class="secondary" data-action="import">Restaurer</button><button class="secondary" data-section="privacy">Comprendre mes données</button></div><button class="text-button" style="margin-top:20px" data-ac="delete-data">Supprimer les données de ce profil</button></section></div>`}
function privacyView(){return `<h1 class="page-title">Tes données, en clair.</h1><div class="panel policy"><h2>Ce qui reste sur ton appareil</h2><p>Prénom ou pseudo facultatif, classe, niveau, tranche d’âge facultative, notes, progression, préférences et retours. Aucun numéro de téléphone, adresse précise ou date de naissance n’est demandé.</p><h2>Quand une connexion est utilisée</h2><p>Le site charge les fichiers nécessaires à la navigation. La bibliothèque charge son index et les articles à la demande. YouTube est contacté seulement si tu actives un lecteur vidéo ; ses règles de confidentialité s’appliquent alors.</p><h2>Nunya Aide, l’assistant IA</h2><p>Rien n’est envoyé tant que tu n’utilises pas Nunya Aide. À ta première question, une session anonyme est créée chez Supabase (serveurs dans l’Union européenne, à Paris) : ni nom, ni e-mail, ni numéro de téléphone. Comme tout service en ligne, Supabase enregistre des données techniques de connexion, par exemple l’adresse IP.</p><p>Ta question, ainsi que l’extrait de la page et ton code (sauf si tu choisis « Ne pas l’envoyer » dans le panneau), passent par notre fonction serveur jusqu’à Groq (serveurs aux États-Unis), qui fait fonctionner le modèle d’IA open source. Selon ses conditions, Groq n’utilise pas ces données pour entraîner ses modèles, mais peut les garder jusqu’à 30 jours pour lutter contre les abus. Nunya n’enregistre ni tes questions ni les réponses : seul un compteur de questions par jour est gardé pour ta session.</p><p>N’écris pas d’informations personnelles dans tes questions. L’IA peut se tromper : vérifie avec ta leçon ou un adulte de confiance. Les sessions anonymes sans activité depuis 30 jours sont supprimées, avec leur compteur. Effacer les données du navigateur supprime aussi ta session sur cet appareil.</p><h2>Ateliers compilés en ligne (C++)</h2><p>Les cours de langages compilés, comme C++, ne peuvent pas compiler sur ton appareil. Quand tu cliques sur Exécuter ou Vérifier dans l’un de ces cours, ton programme et les saisies de test sont envoyés au service gratuit Wandbox (wandbox.org, serveurs au Japon), qui le compile, l’exécute et renvoie l’affichage. Rien d’autre n’est envoyé : ni pseudo, ni progression, ni compte. Comme tout service en ligne, Wandbox reçoit des données techniques de connexion, par exemple l’adresse IP. N’écris pas d’informations personnelles dans ton code. Les autres langages (Python, PHP, JavaScript, SQL, HTML, CSS) s’exécutent entièrement sur ton appareil.</p><h2>Ce qui n’est pas transmis automatiquement</h2><p>Les avis et les statistiques pédagogiques restent locaux. Ils ne sont pas envoyés à un professeur ou à l’équipe. Leur export est volontaire. Aucun classement public, publicité ou vente de données n’est prévu.</p><h2>Profils et âge</h2><p>Le pilote est destiné aux apprenants de 13 ans et plus. Les comptes encadrés pour les plus jeunes sont prévus ultérieurement. L’âge ne verrouille pas les sujets : les recommandations se basent sur les acquis. Un profil local n’est pas une connexion sécurisée ; sur un appareil partagé, protège l’accès à ton navigateur.</p><h2>Exporter ou supprimer</h2><p>Une sauvegarde peut contenir ton pseudo et tes notes : partage-la avec discernement. Effacer les données du navigateur supprime les données locales ; les fichiers que tu as exportés doivent être gérés séparément.</p><p class="profile-line">Version du 5 novembre 2026. Document produit à faire relire avant une collecte centralisée ou un déploiement institutionnel.</p></div>`}
function profilePicker(){let profiles=[];try{profiles=JSON.parse(localStorage.getItem('nunya-profiles')||'[]')}catch{}modal(`<h2 id="modal-title">Un appareil, plusieurs chemins.</h2><p>Les profils sont locaux, sans mot de passe et sans synchronisation. Ils ne protègent pas les données contre une autre personne ayant accès à ce navigateur.</p>${profiles.map((p,i)=>`<button class="assessment-option" data-local-profile="${i}">${esc(p.label)} →</button>`).join('')}<form id="new-local-profile"><label class="field">Nom du nouveau profil<input name="label" maxlength="30" required placeholder="Un pseudo suffit"></label><button class="primary">Créer un nouveau profil</button></form>`)}
function switchLocal(index,label){let profiles=JSON.parse(localStorage.getItem('nunya-profiles')||'[]');const currentId=state.localProfileId||'default';const current=profiles.find(p=>p.id===currentId);const snapshot=JSON.parse(JSON.stringify(state));if(current)current.state=snapshot;else profiles.push({id:currentId,label:state.profile.name||'Mon premier profil',state:snapshot});let target;if(label){target={id:'p-'+Date.now(),label,state:{profile:{name:label,school:'Seconde',level:'beginner',goal:15},done:[],downloads:[],activity:{},minutes:0,lang:'fr',lowData:true,lastCourse:'digital',notes:{},courseAccess:{},resourceDone:[],resourceSaved:[],resourceNotes:{},errors:{},mastery:{},reviewSchedule:{},events:[],preferredTrack:'both',fontScale:1}};profiles.push(target)}else target=profiles[index];if(!target)return;target.state.localProfileId=target.id;localStorage.setItem('nunya-profiles',JSON.stringify(profiles));localStorage.setItem('nunya-state',JSON.stringify(target.state));closeModal();location.reload()}
function glossary(){const terms=[['Variable','Variable','Un nom qui permet de retrouver une valeur.'],['Function','Fonction','Un groupe d’instructions réutilisable.'],['Loop','Boucle','Une répétition d’instructions.'],['File','Fichier','Un ensemble de données enregistré.'],['Download','Télécharger','Enregistrer une ressource depuis un service.'],['Upload','Envoyer un fichier','Transmettre un fichier vers un service.'],['Network','Réseau','Des appareils qui échangent des données.'],['Database','Base de données','Des informations organisées pour être utilisées.'],['Debug','Déboguer','Chercher et corriger une erreur.'],['Privacy','Vie privée','La protection des informations personnelles.'],['Source','Source','L’origine d’une information ou d’un programme.'],['Commit','Commit','Une étape enregistrée dans un historique Git.']];modal(`<h2 id="modal-title">Un mot, un déclic.</h2><p>Petit glossaire français / anglais, disponible hors ligne.</p><label class="field">Chercher un mot<input id="glossary-search" type="search"></label><div id="glossary-list">${terms.map(([en,fr,d])=>`<article class="glossary-term"><strong>${fr} <span>${en}</span></strong><p>${d}</p></article>`).join('')}</div>`)}
function codeLanguage(c){if(c?.id==='python')return 'python';if(c?.id==='javascript')return 'javascript';if(c?.id==='web'){if(activeLesson===0||activeLesson===4)return null;return activeLesson===3?'javascript':'html'}return null}
function editorSeed(c){const code=c.lessons[activeLesson].code;return c.id==='web'&&activeLesson===2?'<h1>Mon titre</h1>\n<style>'+code+'</style>':code}
function stopRuntime(){clearTimeout(runtimeTimer);runtimeTimer=null;if(runtimeWorker){runtimeWorker.terminate();runtimeWorker=null}}
function editorMarkup(lang,seed){return `<span class="eyebrow">ESSAYER DANS CETTE LEÇON</span><h3>Ton code. Ton résultat.</h3><p>Modifie l’exemple, puis exécute-le ici.${lang==='python'?' Le moteur Python (~12 Mo) se charge séparément et peut être enregistré pour le hors ligne.':''}</p><input type="hidden" id="runner-language" value="${lang}"><label class="field" for="code-editor">Mon code · ${lang==='html'?'HTML / CSS':lang==='python'?'Python':'JavaScript'}</label><textarea class="code-editor" id="code-editor" spellcheck="false" maxlength="12000" rows="9">${esc(seed)}</textarea><div class="modal-actions"><button class="primary" data-ac="run-code">▶ Exécuter ici</button><button class="secondary" data-ac="stop-code">■ Arrêter</button>${lang==='python'?'<button class="secondary" data-ac="cache-python">Enregistrer le moteur Python</button>':''}</div><pre id="runner-output" class="runner-output" aria-live="polite">Le résultat apparaîtra ici.</pre><div id="html-preview"></div><p class="profile-line">${lang==='html'?'Prévisualisation HTML sans script ni connexion réseau.':lang==='python'?'Exécution locale, arrêt après 8 secondes. input() et les paquets supplémentaires ne sont pas pris en charge dans ce pilote.':'Exécution locale, arrêt après 2 secondes.'}</p>`}
function workshop(){if($('.lesson-content')&&codeLanguage(activeCourse)){setLessonMode('code');$('#course-code-panel')?.scrollIntoView({block:'start'});return}if(resourceCurrent?.p==='mdn'&&$('.article-reader')){stopRuntime();const old=$('#article-code-panel');if(old){old.scrollIntoView({block:'start'});return}const lang=['html','css'].includes(resourceCurrent.t)?'html':'javascript',first=$('.article-reader pre code')?.textContent||'';$('.article-reader').insertAdjacentHTML('beforebegin',`<section id="article-code-panel" class="context-code-editor">${editorMarkup(lang,first.slice(0,12000)||'console.log("Bonjour !")')}</section>`);$('#article-code-panel').scrollIntoView({block:'start'})}}
const previousLessonMode=setLessonMode;setLessonMode=function(mode){stopRuntime();previousLessonMode(mode);if($('#course-code-panel'))$('#course-code-panel').hidden=mode!=='code'};
function writtenAlternative(r){const domainCourses={maths:['maths-seconde','maths'],physics:['physics'],chemistry:['physics','biology'],biology:['biology'],business:['business']},list=courses.filter(c=>(domainCourses[r.s]||['digital']).includes(c.id));const words=normalize(r.title).split(/\W+/).filter(x=>x.length>3&&!['dans','avec','pour','plus','entre','partie','exemple','introduction'].includes(x));const ranked=list.flatMap(c=>c.lessons.map(l=>({c,l,score:words.filter(w=>normalize(l.title+' '+l.body).includes(w)).length}))).sort((a,b)=>b.score-a.score);const match=ranked.find(x=>x.score>=2);return `<section class="video-written-alternative"><span class="eyebrow">COMPRENDRE SANS VIDÉO</span><h3>Une autre façon d’aborder le sujet.</h3>${match?`<p>${esc(match.l.body)}</p><p><strong>Un exemple pour poser les bases</strong></p><pre><code>${esc(match.l.code)}</code></pre><p>${esc(match.l.explanation)}</p><small>Repère original Nunya associé au thème ; ce texte n’est pas la transcription de la vidéo.</small><button class="secondary" data-school-course="${match.c.id}">Lire le parcours et pratiquer →</button>`:`<p>Avant de regarder, note ce que tu sais déjà sur « ${esc(r.title)} ». Après chaque idée, fais une pause et explique-la avec tes mots. Si tu préfères lire et pratiquer, les parcours Nunya proposent un article, un exemple et un exercice.</p>${list.map(c=>`<button class="secondary" data-school-course="${c.id}">${esc(c.title)} →</button>`).join('')}<small>Leçon écrite correspondante non disponible pour cette vidéo. Ces parcours abordent des bases du domaine, sans être une transcription ni un équivalent exact.</small>`}</section>`}

function runCode(){stopRuntime();const code=$('#code-editor').value,lang=$('#runner-language').value,output=$('#runner-output');output.textContent='';$('#html-preview').innerHTML='';if(lang==='html'){const frame=document.createElement('iframe');frame.title='Prévisualisation HTML isolée';frame.sandbox='';frame.srcdoc='<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src data:; form-action \'none\'">'+code;$('#html-preview').append(frame);output.textContent='Prévisualisation sans script ni accès réseau.';return}const id=++runId;output.textContent=lang==='python'?'Préparation du moteur Python…':'Exécution…';runtimeWorker=new Worker(lang==='python'?'./python-worker.js':'./js-worker.js',{type:'module'});let started=false;runtimeTimer=setTimeout(()=>{stopRuntime();if(output.isConnected)output.textContent='Le moteur a mis trop de temps à démarrer. Vérifie la connexion ou utilise un quiz léger.'},60000);runtimeWorker.onmessage=e=>{if(e.data.id!==id)return;if(e.data.ready&&!started){started=true;clearTimeout(runtimeTimer);output.textContent='';runtimeTimer=setTimeout(()=>{stopRuntime();if(output.isConnected)output.textContent+='\nProgramme arrêté : la limite de temps est atteinte. Vérifie tes boucles.'},8000)}if(e.data.output!==undefined){if(output.textContent==='Exécution…')output.textContent='';output.textContent=(output.textContent+String(e.data.output)+'\n').slice(0,20000)}if(e.data.error){output.textContent=e.data.error;stopRuntime()}if(e.data.done){if(!output.textContent.trim())output.textContent='Programme terminé sans affichage. Utilise print() ou console.log().';stopRuntime()}};runtimeWorker.onerror=()=>{output.textContent='Le moteur n’a pas pu démarrer. Les explications et quiz restent disponibles.';stopRuntime()};if(lang==='javascript'){clearTimeout(runtimeTimer);runtimeTimer=setTimeout(()=>{stopRuntime();if(output.isConnected)output.textContent='Programme arrêté après 2 secondes. Vérifie tes boucles.'},2000)}runtimeWorker.postMessage({id,code})}
async function cachePython(){toast('Enregistrement du moteur Python (~12 Mo)…');try{const cache=await caches.open('nunya-python-v1');await cache.addAll(['./runtime/python/pyodide.js','./runtime/python/pyodide.mjs','./runtime/python/pyodide-lock.json','./runtime/python/pyodide.asm.mjs','./runtime/python/pyodide.asm.wasm','./runtime/python/python_stdlib.zip']);state.pythonCached=true;persist();toast('Moteur Python enregistré pour cet appareil.')}catch{toast('Le moteur n’a pas pu être enregistré. Vérifie la connexion et l’espace disponible.')}}
