const originalBankStart=startPlacement;
startPlacement=async function(){try{assessmentBank=assessmentBank||await readJson('./data/placement_questions.json');placementRun={index:0,answers:[],questions:[],used:[],selected:null};eventLocal('placement_start');showPlacement()}catch{originalBankStart()}};
const oldShowPlacement=showPlacement;
showPlacement=function(){if(!assessmentBank){oldShowPlacement();return}const run=placementRun;if(run.index>=10){finishPlacement();eventLocal('placement_complete');return}if(!run.questions[run.index]){const last=run.answers.at(-1),level=state.profile.level==='comfortable'?3:state.profile.level==='some'?2:1,target=last?Math.min(3,Math.max(1,(run.currentDifficulty||level)+(last.right?1:-1))):level;const desiredSkill=run.index<2?'digital':run.index===2?'reading':run.index===3?'maths':null;let candidates=assessmentBank.filter(q=>!run.used.includes(q.id)&&(!desiredSkill||q.skill===desiredSkill));if(!candidates.length)candidates=assessmentBank.filter(q=>!run.used.includes(q.id));candidates.sort((a,b)=>Math.abs(a.difficulty-target)-Math.abs(b.difficulty-target));const q=candidates[0];run.questions.push(q);run.used.push(q.id);run.currentDifficulty=q.difficulty}const q=run.questions[run.index];modal(`<span class="eyebrow">MON POINT DE DÉPART · ${run.index+1}/10</span><h2 id="modal-title">On trouve un chemin qui te ressemble.</h2><p>Tu peux répondre « Je découvre ». Aucun résultat ne t’empêche d’explorer.</p><div class="progress-line" style="margin:20px 0"><span style="width:${run.index*10}%"></span></div>${q.context?`<pre class="challenge-code">${esc(q.context)}</pre>`:''}<h3 class="assessment-question">${esc(q.q)}</h3>${q.o.map((o,i)=>`<button class="assessment-option" data-placement-answer="${i}" aria-pressed="false">${esc(o)}</button>`).join('')}<button class="assessment-option unsure" data-placement-answer="-1" aria-pressed="false">Je découvre cette notion</button><div class="modal-actions"><button class="primary" id="placement-next" disabled>Continuer →</button></div>`)};
const oldProfile=profileModal;profileModal=function(){oldProfile();const form=$('#profile-form');const select=form.querySelector('[name="school"]');select.innerHTML=(eduData?.classes||[{cycle:'Collège',classes:['6ème','5ème','4ème','3ème']},{cycle:'Lycée',classes:['Seconde','Première','Terminale']}]).map(g=>`<optgroup label="${g.cycle}">${g.classes.map(c=>`<option ${state.profile.school===c?'selected':''}>${c}</option>`).join('')}</optgroup>`).join('')+'<option>Université</option><option>Autodidacte</option>';form.insertAdjacentHTML('afterbegin',`<label class="field">Ce que je veux faire en premier<select name="track"><option value="both" ${state.preferredTrack==='both'?'selected':''}>Réviser et découvrir des métiers</option><option value="school" ${state.preferredTrack==='school'?'selected':''}>Réviser mes cours et mes examens</option><option value="future" ${state.preferredTrack==='future'?'selected':''}>Découvrir un métier ou une compétence</option></select></label><p class="form-note">Pilote pour les 13 ans et plus. Les contenus ne sont jamais verrouillés selon l’âge. Les profils encadrés des plus jeunes seront ajoutés plus tard.</p>`);};
