const baseSector=sectorView;sectorView=function(s){let html=baseSector(s);const evidence=sectorEvidence?.find(x=>x.id===s.id);if(evidence)html=html.replace(/<p class="sector-context">[\s\S]*?<\/p>/,`<div class="institution-note"><span>REPÈRE INSTITUTIONNEL TOGOLAIS</span><p>${esc(evidence.evidence)}</p><small>${esc(evidence.institution)} · source consultée le ${evidence.last_checked} · existence du secteur, sans estimation d’embauche.</small><details><summary>Voir la source et les pistes d’études</summary><a href="${evidence.source_url}" target="_blank" rel="noopener">Source institutionnelle ↗</a><p>Les établissements, concours, séries et conditions d’accès doivent être vérifiés auprès des organismes concernés. La présence d’une formation dans une annonce ancienne ne prouve pas une inscription ouverte.</p></details></div>`);const schoolLinks={health:['SVT','Mathématiques','Français'],tech:['Mathématiques','Anglais'],agri:['SVT','Mathématiques'],energy:['Physique-Chimie','Mathématiques'],education:['Français','Mathématiques']};html+=`<section class="panel career-school-bridge"><h3>Matières utiles à l’école</h3><p>${(schoolLinks[s.id]||['Mathématiques','Français','Anglais']).join(' · ')} — correspondances indicatives à relire, pas des conditions d’admission.</p><button class="text-button" data-section="school">Retrouver Mes cours →</button></section><p class="profile-line">Fiches d’orientation à relire par un professionnel. Les parcours sont des initiations, pas des qualifications.</p>`;return html};
