function importModule(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const f=input.files[0];if(!f||f.size>2000000)throw Error();const d=JSON.parse(await f.text()),c=d.course;if(d.format!=='nunya-module-v1'||!c||!Array.isArray(c.lessons)||!c.lessons.length||c.lessons.length>100||typeof c.id!=='string'||!/^[a-z0-9-]{1,80}$/.test(c.id))throw Error();for(const l of c.lessons)if(!['title','body','code','output','question','explanation'].every(k=>typeof l[k]==='string'&&l[k].length<20000)||!Array.isArray(l.options)||l.options.length!==3||!l.options.every(x=>typeof x==='string'&&x.length<2000)||!Number.isInteger(l.answer)||l.answer<0||l.answer>2)throw Error();if(!courses.some(x=>x.id===c.id)){const safe={id:c.id,title:String(c.title||'Parcours importé').slice(0,100),en:String(c.title||'Parcours importé'),category:'PARCOURS IMPORTÉ',domain:'tech',type:'subject',glyph:'↳',color:'#e4eadb',desc:'Contenu importé depuis un fichier. Sa source et sa qualité sont à vérifier.',enDesc:'Parcours importé',level:'Découverte',duration:c.lessons.length*10,lessons:c.lessons,status:'brouillon',track:'future'};for(const k of ['author','provider','license','original_title','source_notes'])if(typeof c[k]==='string')safe[k]=c[k].slice(0,500);for(const k of ['source_url','license_url']){try{const u=new URL(c[k]);if(u.protocol==='https:')safe[k]=u.href}catch{}}courses.push(safe);state.importedModules=state.importedModules||[];state.importedModules.push(safe)}if(!state.downloads.includes(c.id))state.downloads.push(c.id);localStorage.setItem('nunya-pack-'+c.id,JSON.stringify(c));persist();render();toast('Parcours importé sur cet appareil. Vérifie sa provenance avant de l’utiliser.')}catch{toast('Ce fichier ne contient pas un parcours Nunya valide.')}};input.click()}
if(Array.isArray(state.importedModules))for(const c of state.importedModules)if(c&&typeof c.id==='string'&&Array.isArray(c.lessons)&&!courses.some(x=>x.id===c.id))courses.push(c);
