searchModal=function(){closeModal();navigate('explore');queueMicrotask(()=>$('#library-search')?.focus())};$('#search-btn').onclick=searchModal;
const examSources=[{id:'CEPD',label:'CEPD · fin du primaire',source:'https://ecole.gouv.tg/primaire/'},{id:'BEPC',label:'BEPC · fin du collège',source:'https://ecole.gouv.tg/college/mod/folder/view.php?id=22&lang=fr'},{id:'BAC I',label:'BAC I · première partie',source:'https://ecole.gouv.tg/lycee/mod/folder/view.php?id=1&lang=fr'},{id:'BAC II',label:'BAC II · deuxième partie',source:'https://service-public.gouv.tg/service/62197bd433c0179346497bc0/emploi-securite-sociale/demande-de-diplome-bac-ii'}];
const originalSchoolView=schoolView;schoolView=function(){let html=originalSchoolView();html+=`<section class="panel exam-directory"><h3>Mes grands rendez-vous scolaires</h3><div class="exam-options">${examSources.map(x=>`<button class="secondary" data-exam="${x.id}">${x.id} →</button>`).join('')}</div><p>Le cadre prend en charge CEPD, BEPC, BAC I et BAC II. Les contenus de préparation disponibles et les dates sont distingués : aucun calendrier 2027 non confirmé n’est affiché comme officiel.</p><details><summary>Enseignement technique et supérieur</summary><p>Le référentiel est extensible. Le CFA et le BTS figurent aussi dans un calendrier institutionnel 2026 ; leur préparation complète reste à documenter. Les filières, épreuves et coefficients devront être vérifiés avant publication.</p></details></section>`;return html};
document.addEventListener('click',e=>{const b=e.target.closest('button[data-exam]');if(!b)return;e.stopImmediatePropagation();const x=examSources.find(x=>x.id===b.dataset.exam);if(x)openExam(x);},true);
let officialDocuments=null,examFilter={exam:'',year:'all',series:'all',q:''};
async function openExam(x){examFilter={exam:x.id,year:'all',series:'all',q:''};if(!officialDocuments){modal(`<h2 id="modal-title">${x.label}</h2><p role="status">Chargement des annales officielles…</p>`);try{officialDocuments=await readJson('./data/official_exam_documents.json')}catch{officialDocuments=[]}}renderExamLibrary()}
function renderExamLibrary(){const x=examSources.find(x=>x.id===examFilter.exam);if(!x)return;const all=(officialDocuments||[]).filter(d=>d.exam===x.id),rows=all.filter(d=>(examFilter.year==='all'||d.year===examFilter.year)&&(examFilter.series==='all'||d.series===examFilter.series)&&normalize(d.title).includes(normalize(examFilter.q)));modal(`<span class="eyebrow">DOCUMENTS · PORTAIL OFFICIEL DU TOGO</span><h2 id="modal-title">${x.label}</h2><p>${all.length?all.length+(x.id==='BAC II'?' documents de Terminale : compositions régionales et corrigés, hébergés sur ecole.gouv.tg. Ce ne sont pas des annales nationales du BAC II.':' sujets référencés depuis ecole.gouv.tg. Choisis un document pour le consulter ici.'):'Le dossier BAC II du portail consulté ne contient pas encore de PDF. Les parcours et le plan de révision restent disponibles ; nous ajouterons les sujets lorsqu’une source officielle les publiera.'}</p>${all.length?`<div class="exam-filters"><label>Année<select id="exam-year"><option value="all">Toutes</option>${[...new Set(all.map(d=>d.year))].sort().reverse().map(y=>`<option ${examFilter.year===y?'selected':''}>${y}</option>`).join('')}</select></label>${['BAC I','BAC II'].includes(x.id)?`<label>Série<select id="exam-series"><option value="all">Toutes</option>${[...new Set(all.map(d=>d.series))].sort().map(y=>`<option ${examFilter.series===y?'selected':''}>${esc(y)}</option>`).join('')}</select></label>`:''}<label>Matière<input id="exam-search" type="search" value="${esc(examFilter.q)}" placeholder="Mathématiques, français, SVT…"></label></div><p class="profile-line">${rows.length} document(s) · PDF à la source · les corrigés sont identifiés, jamais inventés par Nunya.</p><div class="exam-document-list">${rows.slice(0,50).map(d=>`<button data-exam-document="${d.id}"><span><strong>${esc(d.title)}</strong><small>${esc(d.year)}${d.series?' · série '+esc(d.series):''}${d.document_type==='composition-regionale-terminale'?' · composition régionale':''}${d.correction?' · CORRIGÉ':''}</small></span><b>Lire ici →</b></button>`).join('')||'<p>Aucun document pour ces filtres.</p>'}${rows.length>50?'<p>Précise l’année, la série ou la matière pour voir les autres documents.</p>':''}</div>`:''}<div class="modal-actions"><button class="primary" data-ac="exam-plan">Organiser mes révisions →</button><button class="secondary" data-section="school">Mes matières & exercices</button></div><details class="lesson-sources"><summary>Source et disponibilité</summary><a href="${x.source}" target="_blank" rel="noopener">Consulter la source officielle ↗</a><p>Consultation du 1er novembre 2026. Les PDF restent hébergés par le portail officiel ; ils ne sont pas copiés pour le hors ligne. La mention corrigé suit le nom du fichier publié par le portail. Aucun coefficient ni calendrier futur n’est supposé.</p></details>`,true)}
document.addEventListener('change',e=>{if(e.target.id==='exam-year'||e.target.id==='exam-series'){examFilter[e.target.id==='exam-year'?'year':'series']=e.target.value;renderExamLibrary()}});
let examSearchTimer;document.addEventListener('input',e=>{if(e.target.id==='exam-search'){examFilter.q=e.target.value;clearTimeout(examSearchTimer);examSearchTimer=setTimeout(()=>{renderExamLibrary();$('#exam-search')?.focus()},250)}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.examDocument){e.stopImmediatePropagation();const d=officialDocuments?.find(d=>d.id===b.dataset.examDocument);if(!d)return;modal(`<button class="text-button" data-return-exams>← Les sujets ${esc(d.exam)}</button><h2 id="modal-title">${esc(d.title)} · ${d.year}</h2><p class="profile-line">${d.document_type==='composition-regionale-terminale'?'Composition régionale · préparation':'Sujet officiel'} · ${esc(d.exam)}${d.series?' · série '+esc(d.series):''} · une connexion est nécessaire.</p><iframe class="official-pdf" title="Sujet officiel : ${esc(d.title)}" src="${esc(d.url)}" referrerpolicy="no-referrer"></iframe><p>Le lecteur PDF dépend de ton navigateur. S’il reste vide, tu peux <a href="${esc(d.url)}" target="_blank" rel="noopener">ouvrir le document officiel ↗</a></p><p class="profile-line">Nunya n’a pas modifié ce document. Les compositions régionales ne sont pas présentées comme des sujets nationaux du BAC II.</p>`,true)}else if(b.hasAttribute('data-return-exams')){e.stopImmediatePropagation();renderExamLibrary()}},true);

function librarySubjects(){if(libraryFilter.provider!=='nunya')return [['all','Tout','✳'],...extensionSubjects];const used=new Set(courses.map(c=>c.domain==='tech'?'technology':c.domain));const unique=new Map([...extensionSubjects,...SUBJECTS.filter(x=>!['all','tech'].includes(x[0]))].map(x=>[x[0],x]));return [['all','Tous les domaines','✳'],...[...unique.values()].filter(x=>used.has(x[0]))]}
function guidedCoursesView(){const list=filteredOriginal();if(!list.length)return '<div class="empty-state"><h3>Aucun parcours pour ces filtres.</h3><p>Essaie une autre matière ou explore les ressources de la bibliothèque.</p><button class="secondary" data-library-tab="resources">Voir les ressources →</button></div>';if(libraryFilter.subject!=='all'||libraryFilter.q)return `<div class="course-grid explore-grid">${list.map(courseCard).join('')}</div>`;const groups=[['Mes cours & examens',c=>c.track==='school'],['Numérique & bureautique',c=>c.track!=='school'&&['tech','telecom'].includes(c.domain)],['Sciences & santé',c=>c.track!=='school'&&['maths','physics','biology','health'].includes(c.domain)],['Économie & projets',c=>c.track!=='school'&&['business','fintech'].includes(c.domain)],['Métiers & terrain',c=>c.track!=='school'&&!['tech','telecom','maths','physics','biology','health','business','fintech'].includes(c.domain)]];return `<div class="course-collections">${groups.map(([label,filter],i)=>{const rows=list.filter(filter);return rows.length?`<details class="course-collection" ${i===0?'open':''}><summary><span>${label}</span><small>${rows.length} parcours</small><b aria-hidden="true">⌄</b></summary><div class="course-grid explore-grid">${rows.map(courseCard).join('')}</div></details>`:''}).join('')}</div>`}
